:root {
  --bg-card: #f0ebe0;
  --bg-header: #2c4a3e;
  --bg-stat: #3a6b58;
  --bg-panel: #faf7f0;
  --bg-bar-track: #ddd6c8;
  --color-accent: #c8873a;
  --color-low: #6db88a;
  --color-mid: #e0a040;
  --color-high: #c05a3a;
  --color-good: #4a9aba;
  --color-pass: #2e7d52;
  --color-warn: #b8720a;
  --color-pass-bg: #d4edda;
  --color-warn-bg: #fdeacc;
  --text-header: #f0ebe0;
  --text-dark: #1e2d28;
  --text-mid: #4a5e56;
  --text-muted: #7a8e86;
  --border-card: #c8bfaa;
  --border-section: #d8d0c0;
}

.well-log {
  width: 480px;
  background: var(--bg-card);
  border: 2px solid var(--border-card);
  border-radius: 10px;
  overflow: hidden;
  font-size: 13px;
  color: var(--text-dark);
}

.log-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.log-badge {
  background: var(--color-accent);
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 1px;
}

.log-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-header);
  margin: 0;
  letter-spacing: 0.5px;
}

.log-subtitle {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}

.log-date {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-accent);
  letter-spacing: 0.5px;
}

.log-id {
  font-size: 11px;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

.well-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  background: var(--bg-stat);
  border-bottom: 2px solid var(--border-card);
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 6px;
  border-right: 1px solid rgba(255,255,255,0.12);
}

.stat-block:last-child {
  border-right: none;
}

.stat-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-header);
  line-height: 1;
}

.stat-unit {
  font-size: 10px;
  font-weight: 400;
  color: var(--color-accent);
  margin-left: 1px;
}

.stat-label {
  font-size: 10px;
  color: var(--text-muted);
  margin-top: 3px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
}

.log-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}

.readings-panel {
  padding: 10px 12px;
  border-right: 1px solid var(--border-section);
}

.status-panel {
  padding: 10px 12px;
  background: var(--bg-panel);
}

.panel-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-mid);
  margin: 0 0 8px 0;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--border-section);
}

.readings-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.reading-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.reading-name {
  font-size: 11px;
  color: var(--text-mid);
  width: 80px;
  flex-shrink: 0;
}

.reading-bar-wrap {
  flex: 1;
  height: 6px;
  background: var(--bg-bar-track);
  border-radius: 3px;
  overflow: hidden;
}

.reading-bar {
  display: block;
  height: 100%;
  border-radius: 3px;
}

.bar-low {
  width: 20%;
  background: var(--color-low);
}

.bar-mid {
  width: 52%;
  background: var(--color-mid);
}

.bar-high {
  width: 78%;
  background: var(--color-high);
}

.bar-good {
  width: 88%;
  background: var(--color-good);
}

.reading-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-dark);
  width: 58px;
  text-align: right;
  flex-shrink: 0;
}

.status-badge-row {
  display: flex;
  gap: 6px;
  margin-bottom: 8px;
}

.status-chip {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 12px;
}

.chip-pass {
  background: var(--color-pass-bg);
  color: var(--color-pass);
}

.chip-warn {
  background: var(--color-warn-bg);
  color: var(--color-warn);
}

.notes-text {
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-mid);
  margin: 0 0 10px 0;
}

.log-footer {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-top: 8px;
  border-top: 1px solid var(--border-section);
}

.inspector-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-muted);
}

.inspector-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dark);
  flex: 1;
}

.cert-badge {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-accent);
  background: rgba(200,135,58,0.12);
  border: 1px solid var(--color-accent);
  border-radius: 4px;
  padding: 2px 6px;
  letter-spacing: 0.5px;
}
